package com.google.javascript.rhino.jstype;

import com.google.common.base.Preconditions;
import com.google.common.collect.ImmutableList;
import com.google.common.collect.Iterables;
import com.google.common.collect.Lists;
import com.google.common.collect.Sets;
import com.google.javascript.rhino.ErrorReporter;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class FunctionType_setPrototype_TriageGen2Test {

    private FunctionType functionType;
    private PrototypeObjectType prototypeMock;

    @Before
    public void setUp() {
        // Since FunctionType is a complex class, we use a mock or a real instance depending on needs.
        // However, to test the logic of setPrototype which calls many internal methods, 
        // we mock the FunctionType to control the branching logic.
        functionType = mock(FunctionType.class);
        prototypeMock = mock(PrototypeObjectType.class);
    }

    @Test
    public void testSetPrototype_NullPrototype() {
        boolean result = functionType.setPrototype(null);
        assertFalse("Should return false when prototype is null", result);
    }

    @Test
    public void testSetPrototype_ConstructorSameAsInstanceType() {
        when(functionType.isConstructor()).thenReturn(true);
        when(functionType.getInstanceType()).thenReturn(prototypeMock);

        boolean result = functionType.setPrototype(prototypeMock);
        assertFalse("Should return false if isConstructor is true and prototype is the same as getInstanceType", result);
    }

    @Test
    public void testSetPrototype_SuccessOrdinaryFunction() {
        when(functionType.isConstructor()).thenReturn(false);
        when(functionType.isInterface()).thenReturn(false);

        boolean result = functionType.setPrototype(prototypeMock);

        assertTrue("Should return true for successful prototype setting", result);
        Mockito.verify(prototypeMock).setOwnerFunction(functionType);
        Mockito.verify(functionType).clearCachedValues();
    }

    @Test
    public void testSetPrototype_SuccessConstructorWithSuperClass() {
        when(functionType.isConstructor()).thenReturn(true);
        when(functionType.isInterface()).thenReturn(false);

        FunctionType superClassMock = mock(FunctionType.class);
        when(functionType.getSuperClassConstructor()).thenReturn(superClassMock);

        boolean result = functionType.setPrototype(prototypeMock);

        assertTrue(result);
        Mockito.verify(superClassMock).addSubType(functionType);
        Mockito.verify(functionType).clearCachedValues();
    }

    @Test
    public void testSetPrototype_SuccessConstructorNoSuperClass() {
        when(functionType.isConstructor()).thenReturn(true);
        when(functionType.isInterface()).thenReturn(false);
        when(functionType.getSuperClassConstructor()).thenReturn(null);

        boolean result = functionType.setPrototype(prototypeMock);

        assertTrue(result);
        Mockito.verify(functionType).clearCachedValues();
    }

    @Test
    public void testSetPrototype_SuccessInterfaceWithSuperClassAndExtendedInterfaces() {
        when(functionType.isConstructor()).thenReturn(false);
        when(functionType.isInterface()).thenReturn(true);

        FunctionType superClassMock = mock(FunctionType.class);
        when(functionType.getSuperClassConstructor()).thenReturn(superClassMock);

        ObjectType extendedInterface = mock(ObjectType.class);
        FunctionType extendedInterfaceConstructor = mock(FunctionType.class);
        when(extendedInterface.getConstructor()).thenReturn(extendedInterfaceConstructor);
        when(functionType.getExtendedInterfaces()).thenReturn(Collections.singleton(extendedInterface));

        boolean result = functionType.setPrototype(prototypeMock);

        assertTrue(result);
        Mockito.verify(superClassMock).addSubType(functionType);
        Mockito.verify(extendedInterfaceConstructor).addSubType(functionType);
        Mockito.verify(functionType).clearCachedValues();
    }

    @Test
    public void testSetPrototype_SuccessInterfaceWithSuperClassNoExtendedInterfaces() {
        when(functionType.isConstructor()).thenReturn(false);
        when(functionType.isInterface()).thenReturn(true);

        FunctionType superClassMock = mock(FunctionType.class);
        when(functionType.getSuperClassConstructor()).thenReturn(superClassMock);
        when(functionType.getExtendedInterfaces()).thenReturn(Collections.emptyList());

        boolean result = functionType.setPrototype(prototypeMock);

        assertTrue(result);
        Mockito.verify(superClassMock).addSubType(functionType);
    }

    @Test
    public void testSetPrototype_SuccessInterfaceWithExtendedInterfaceMissingConstructor() {
        when(functionType.isConstructor()).thenReturn(false);
        when(functionType.isInterface()).thenReturn(true);

        ObjectType extendedInterface = mock(ObjectType.class);
        when(extendedInterface.getConstructor()).thenReturn(null);
        when(functionType.getExtendedInterfaces()).thenReturn(Collections.singleton(extendedInterface));
        when(functionType.getSuperClassConstructor()).thenReturn(null);

        boolean result = functionType.setPrototype(prototypeMock);

        assertTrue(result);
        // Should not throw NullPointerException when interface constructor is null
        Mockito.verify(functionType).clearCachedValues();
    }
}
